{
  "aggregate_id": "DEF-NRS-484A-130::motor_vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition expressly excludes."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The contract describes a motor vehicle, matching the self-propelled, non-rail admitting clause without a class-specific exception."
    },
    {
      "class": "ru.child",
      "verdict": "contradicted",
      "reason": "The contract describes a pedestrian person rather than a transport device, and using a motorized wheelchair does not make that person a vehicle."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "An admitted member must satisfy the self-propelled, non-rail vehicle contract or a separately classed motorcycle or moped contract, making the quoted coverage complete."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The controlling definition expressly excludes electric bicycles."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The controlling definition expressly excludes electric scooters."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation does not independently establish admission, while every admitted member satisfies one of the three quoted covering contracts."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "The fire-fighting designation adds no independent admission criterion, and every admitted member satisfies one of the three quoted covering contracts."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The jurisdiction-defined moped is engine-propelled and non-rail, and its definition separates it from the expressly excluded electric bicycles and electric scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The contract supplies the admitting clause's self-propulsion and non-rail requirements while separating the jurisdiction's separately classed powered two-wheelers."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract describes a motor vehicle on two or three wheels, which the admitting clause reaches without an exception for motorcycles."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service and identifying equipment add no independent admission criterion, while every admitted member satisfies one of the three quoted covering contracts."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "contradicted",
      "reason": "The contract describes a person rather than a transport device, so a wheelchair's propulsion does not bring its occupant within the vehicle definition."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "contradicted",
      "reason": "The contract still describes a pedestrian person, and neither assistance nor wheelchair use turns that person into a transport device."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The contract describes on-track equipment, which fails the express requirement that a motor vehicle not be operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose motor-vehicle contract supplies self-propulsion and non-rail operation."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Hire status alone does not establish admission, but every admitted passenger vehicle satisfies one of the three quoted covering contracts."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The lengthened passenger-vehicle branch does not exclude separately classed powered two-wheelers, so an admitted member need not carry the sole covering class ru.motor_vehicle."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "A merely drawn trailer fails self-propulsion, while any combination admitted as a self-propelled non-rail vehicle must itself satisfy one of the quoted covering contracts."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus, whose motor-vehicle contract meets the admitting clause regardless of its transit service."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The contract expressly describes a motor vehicle, and its goods-carrying purpose introduces no exception to the admitting clause."
    }
  ]
}

